import jetbrains.buildServer.configs.kotlin.*
import jetbrains.buildServer.configs.kotlin.buildFeatures.XmlReport
import jetbrains.buildServer.configs.kotlin.buildFeatures.xmlReport
import jetbrains.buildServer.configs.kotlin.buildSteps.script
import jetbrains.buildServer.configs.kotlin.triggers.vcs
import jetbrains.buildServer.configs.kotlin.vcs.GitVcsRoot
import java.io.File

/*
 * apache/zookeeper → TeamCity, generated by the TeamCity migration factory.
 * Design, parity checklist and sizing evidence: work/design/apache__zookeeper.md.
 * Parity target: upstream GitHub Actions (.github/workflows/ci.yaml, e2e.yaml, scripts.yaml,
 * website.yaml) @ 5dd643fb. The ASF Jenkins pipelines (Jenkinsfile*, cron @daily / PreCommit /
 * OWASP / s390x) and the PR-only / manual GHA jobs are included as PAUSED configs.
 * Upstream has no Windows or macOS lanes, so every cell here is Linux.
 */

version = "2026.03"

// GitHub App connection PROJECT_EXT_66 ("TeamCity - demo.teamcity.com", at _Root). Its token id only
// exists after the App is installed on arokhin/zookeeper and the connection is authorized (approval
// checkpoint), so it arrives as a Versioned Settings DSL context parameter, never as a literal
// (Lesson 9). It is a reference, not a secret. Until it is set the root clones the public fork anonymously.
val githubTokenId: String = DslContext.getParameter("githubTokenId", "")

val SourcesVcs = GitVcsRoot({
    id("Sources")
    name = "arokhin/zookeeper (fast-forward mirror of apache/zookeeper)"
    url = "https://github.com/arokhin/zookeeper.git"
    branch = "refs/heads/master"
    branchSpec = "+:refs/heads/master"
    if (githubTokenId.isNotBlank()) {
        authMethod = token {
            userName = "oauth2"
            tokenId = githubTokenId
        }
    } else {
        authMethod = anonymous()
    }
})

fun readScript(name: String) = File(DslContext.baseDir, "scripts/$name").readText()

// Every step is a raw bash script, not the Maven runner. The runner can rewrite or drop arguments
// (Lesson 3), and upstream's exact `mvn ... ${{ matrix.profile.args }}` lines are what we mirror.
// The scripts contain no '%' characters, so TeamCity's %param% substitution cannot mangle them; every
// TeamCity value reaches them as an env.* param defined on the build type.
fun BuildSteps.bashStep(stepName: String, vararg parts: String) {
    val body = (listOf("common.sh") + parts).joinToString("\n") { readScript(it) }
    script {
        name = stepName
        scriptContent = "#!/usr/bin/env bash\nset -eo pipefail\n$body"
    }
}

// Tier selection (Lesson 11). The Default pool is discrete EC2 bundles: Small=2 CPU/3.7 GB,
// Medium=4/7.6 GB, Large=8/15 GB. cpuCount alone picks the tier, so no memory requirement is set:
// it would be inert documentation, not a lever. Names copied verbatim from the probe (Lesson 4).
enum class Tier(val cpus: Int) { SMALL(2), MEDIUM(4), LARGE(8) }

fun Requirements.linux(tier: Tier) {
    equals("teamcity.agent.jvm.os.family", "Linux")
    equals("teamcity.agent.hardware.cpuCount", tier.cpus.toString())
}

fun ParametrizedWithType.common(jdk: Int) {
    // Must be spelled exactly as the agents report it (env.JDK_17_0 / env.JDK_25_0, per the probe).
    // A typo here is an implicit requirement that makes every agent incompatible with no runtime error (Lesson 4).
    param("env.JAVA_HOME", "%env.JDK_${jdk}_0%")
    // GHA uses the runner image's Maven 3.9.x. The agents have apt Maven 3.8.7 plus the TeamCity tool maven3_9
    // (installed on demand); the tool matches upstream's major/minor. Proven live on TcMf_JenkinsCasc.
    param("env.MF_MVN", "%teamcity.tool.maven3_9%/bin/mvn")
    param("env.MAVEN_OPTS", "-Djansi.force=true")
    // Per-build tool state outside the checkout (see scripts/common.sh: apache-rat and shfmt scan the tree).
    param("env.MF_TOOLS", "%system.teamcity.build.tempDir%/mf-tools")
}

fun BuildType.sources() {
    vcs {
        root(SourcesVcs)
        // The root pom runs mavanagaiata:commit in `validate` (reads .git) and every GHA job starts with
        // `git log -n1`, so the agent needs a real .git: agent-side checkout.
        checkoutMode = CheckoutMode.ON_AGENT
        cleanCheckout = true
    }
}

// Upstream uploads these reports only `if: failure()`. TeamCity has no "on failure only" publish mode
// (NORMALLY_FINISHED / SUCCESSFUL / ALWAYS), so ALWAYS is the closest superset: it also keeps reports from
// builds that hit the execution timeout. Upstream redirects test output to files (redirectTestOutputToFile),
// so on green builds this costs storage only. Revisit in phase 6 if the archives are large.
fun BuildType.failureReports(vararg rules: String) {
    artifactRules = rules.joinToString("\n")
    publishArtifacts = PublishMode.ALWAYS
}

// ---------------------------------------------------------------- ci.yaml "mvn" (4 cells, live)

data class MvnCell(val idPart: String, val profile: String, val jdk: Int, val args: String, val tier: Tier, val timeoutMin: Int)

// `args` copied verbatim from ci.yaml matrix.profile (fail-fast: false, runs-on: ubuntu-24.04, timeout 360).
// Timeouts: about 3x the worst observed GHA job time (brief: static 2.1–3.3, cppunit 8.9–10.9, java-tests
// 67.0–72.7 min), because the local repo is cold every build (no setup-java cache, Lesson 7). All stay
// within upstream's 360.
// Sizing (pass 1): GHA ubuntu-24.04 runners are 4 vCPU / 16 GB, so Medium (4 CPU / 7.6 GB) matches the CPU count.
// java-tests pins -Dsurefire-forkcount=1 (CPU-independent, GOTCHAS): 1 surefire fork, -Xmx512m
// (zookeeper-server/pom.xml argLine), plus the Maven JVM: about 1.5 GB, well inside 7.6 GB. The ZooKeeper
// suite is timing-sensitive (upstream reruns failures 5x), so the tier keeps upstream's CPU count rather than Small.
val mvnCells = listOf(
    MvnCell("Jdk17", "full-build-jdk17", 17,
        "-Pfull-build apache-rat:check verify -DskipTests spotbugs:check checkstyle:check", Tier.MEDIUM, 30),
    MvnCell("Jdk25", "full-build-jdk25", 25,
        "-Pfull-build apache-rat:check verify -DskipTests spotbugs:check checkstyle:check", Tier.MEDIUM, 30),
    MvnCell("JavaTests", "full-build-java-tests", 25,
        "-Pfull-build verify -Dsurefire-forkcount=1 -DskipCppUnit -Dsurefire.rerunFailingTestsCount=5", Tier.MEDIUM, 240),
    MvnCell("CppUnitTests", "full-build-cppunit-tests", 25,
        "-Pfull-build verify -Dtest=_ -DfailIfNoTests=false", Tier.MEDIUM, 45),
)

fun mvnCellType(c: MvnCell): BuildType = BuildType({
    id("Ci_${c.idPart}")
    name = "mvn (${c.profile}, JDK ${c.jdk})"
    description = "GHA ci.yaml job mvn [${c.profile}]: mvn ${c.args}"
    sources()
    params {
        common(c.jdk)
        param("env.MF_MVN_ARGS", c.args)
    }
    steps {
        bashStep("Install C dependencies", "c-deps.sh")
        bashStep("Build with Maven (${c.profile})", "mvn-ci.sh")
    }
    requirements { linux(c.tier) }
    failureConditions { executionTimeoutMin = c.timeoutMin }
    failureReports(
        "**/target/surefire-reports/** => surefire-reports-${c.profile}.zip",
        "**/target/failsafe-reports/** => failsafe-reports-${c.profile}.zip",
        "zookeeper-client/zookeeper-client-c/target/c/TEST-*.txt => cppunit-logs-${c.profile}.zip",
    )
    features {
        // Static-analysis gates follow upstream: spotbugs:check / checkstyle:check / apache-rat:check fail
        // the Maven build, hence the step. These imports are only for visibility, with no extra failure conditions.
        if (c.args.contains("checkstyle:check")) {
            xmlReport {
                reportType = XmlReport.XmlReportType.CHECKSTYLE
                rules = "+:**/target/checkstyle-result.xml"
            }
            xmlReport {
                reportType = XmlReport.XmlReportType.FINDBUGS
                rules = "+:**/target/spotbugsXml.xml"
            }
        }
        if (!c.args.contains("-DskipTests")) {
            xmlReport {
                reportType = XmlReport.XmlReportType.JUNIT
                rules = "+:**/target/surefire-reports/TEST-*.xml"
            }
        }
    }
})

val mvnTypes = mvnCells.map { mvnCellType(it) }

// ---------------------------------------------------------------- e2e.yaml "compatibility" (8 cells, live)

val e2eZk = listOf("3.7.2", "3.8.6", "3.9.5", "nightly")

// Each cell builds the tree itself (`mvn package -DskipTests`, no -Pfull-build) exactly as upstream does:
// upstream cells share nothing, so no artifact dependency is invented (Lesson 6). Small tier: an upstream job
// takes 0.8–1.5 min (compile only, with a warm cache). runs-on: ubuntu-latest, timeout 360; here 30 (cold repo).
fun e2eType(jdk: Int, zk: String): BuildType = BuildType({
    id("E2e_Jdk${jdk}_Zk${zk.replace(".", "")}")
    name = "compatibility (JDK $jdk, ZooKeeper $zk)"
    description = "GHA e2e.yaml job compatibility [jdk=$jdk, zk=$zk]: nightly ↔ $zk server/client connectivity via tools/ci/test-connectivity.py"
    sources()
    params {
        common(jdk)
        param("env.MF_JDK", jdk.toString())
        param("env.MF_ZK", zk)
    }
    steps {
        bashStep("Install C dependencies", "c-deps.sh")
        bashStep("Build and test connectivity (ZooKeeper $zk)", "e2e.sh")
    }
    requirements { linux(Tier.SMALL) }
    failureConditions { executionTimeoutMin = 30 }
    failureReports("logs/** => zookeeper-logs.zip", "apache-zookeeper-*-bin/logs/** => zookeeper-$zk-logs.zip")
})

val e2eTypes = listOf(17, 25).flatMap { jdk -> e2eZk.map { e2eType(jdk, it) } }

// ---------------------------------------------------------------- scripts.yaml "ScriptQA" (2 cells, live)

// Upstream timeout is 3 min per job. Here 10: the agent first has to check out and download shfmt
// (and apt-install shellcheck) on a cold agent, which GHA's image gets for free.
fun scriptQaType(idPart: String, title: String, vararg parts: String): BuildType = BuildType({
    id("ScriptQa_$idPart")
    name = title
    description = "GHA scripts.yaml job ${title}"
    sources()
    params { common(17) }
    steps { bashStep(title, *parts) }
    requirements { linux(Tier.SMALL) }
    failureConditions { executionTimeoutMin = 10 }
})

val scriptQaTypes = listOf(
    scriptQaType("Shfmt", "shfmt", "shfmt.sh", "shfmt-check.sh"),
    // Upstream's ShellCheck job also installs shfmt: run-shellcheck.sh lists the files with `shfmt -f .`.
    scriptQaType("ShellCheck", "ShellCheck", "shfmt.sh", "shellcheck.sh"),
)

// ---------------------------------------------------------------- website.yaml (1 cell, live)

val Website = BuildType({
    id("Website")
    name = "website-site (JDK 25, Node 24)"
    description = "GHA website.yaml job website-site: npm ci, Playwright browsers, mvn -pl zookeeper-website site (lint, typecheck, vitest, build, Playwright e2e)"
    sources()
    params {
        common(25)
        param("env.MF_NODE_VERSION", "24.18.1")
    }
    steps {
        bashStep("Website (npm ci, Playwright, mvn site)", "website.sh")
    }
    // Upstream pins runs-on: ubuntu-24.04 because Playwright's browsers need ICU 74; the agents are 24.04 too.
    // Medium: Node build + Chromium/Firefox/WebKit e2e on GHA's 4 vCPU (job time 5.2–5.6 min).
    requirements { linux(Tier.MEDIUM) }
    // Upstream 120. Here 60: about 10x the observed time, for cold Node/npm/Playwright downloads.
    failureConditions { executionTimeoutMin = 60 }
    failureReports(
        "zookeeper-website/playwright-report/** => website-playwright-report.zip",
        "zookeeper-website/test-results/** => website-test-results.zip",
    )
})

val liveTypes: List<BuildType> = mvnTypes + e2eTypes + scriptQaTypes + Website

// ---------------------------------------------------------------- paused lanes (Lesson 17)

fun pausedMvn(idPart: String, title: String, source: String, reason: String, jdk: Int, args: String,
              extraReq: Requirements.() -> Unit = { linux(Tier.MEDIUM) }): BuildType = BuildType({
    id("Side_$idPart")
    name = "[paused] $title"
    description = "$source · PAUSED: $reason"
    paused = true
    sources()
    params {
        common(jdk)
        param("env.MF_MVN_ARGS", args)
    }
    steps {
        bashStep("Install C dependencies", "c-deps.sh")
        bashStep(title, "mvn-ci.sh")
    }
    requirements(extraReq)
    // ASF Jenkins: timeout(time: 2, unit: 'HOURS').
    failureConditions { executionTimeoutMin = 120 }
    features {
        xmlReport {
            reportType = XmlReport.XmlReportType.JUNIT
            rules = "+:**/target/surefire-reports/TEST-*.xml"
        }
    }
})

// Jenkinsfile / Jenkinsfile-s390x: `mvn verify spotbugs:check checkstyle:check -Pfull-build -Dsurefire-forkcount=4`.
// forkcount=4 is CPU-independent; 4 forks × -Xmx512m plus the Maven JVM ≈ 3.5 GB, which fits Medium's 7.6 GB.
val jenkinsArgs = "verify spotbugs:check checkstyle:check -Pfull-build -Dsurefire-forkcount=4"

val jenkinsTypes = listOf(17, 25).map { jdk ->
    pausedMvn("JenkinsDaily_Jdk$jdk", "ASF Jenkins daily (JDK $jdk)", "ASF Jenkins Jenkinsfile (cron @daily, label Hadoop) [jdk_${jdk}_latest]",
        "secondary nightly CI on ci-hadoop.apache.org (unreachable from here, no status on GitHub commits); GHA ci.yaml is the primary per-push CI and is mirrored live. Un-pause on user decision",
        jdk, jenkinsArgs)
} + listOf(17, 25).map { jdk ->
    pausedMvn("JenkinsS390x_Jdk$jdk", "ASF Jenkins s390x daily (JDK $jdk)", "ASF Jenkins Jenkinsfile-s390x (cron @daily, label s390x) [jdk_${jdk}_latest]",
        "no s390x agents on demo.teamcity.com (probe: x86_64 EC2 only)", jdk, jenkinsArgs) {
        // Kept so that un-pausing without an s390x agent reads as "no compatible agents", not as a silent x86 run.
        equals("teamcity.agent.jvm.os.family", "Linux")
        equals("teamcity.agent.jvm.os.arch", "s390x")
    }
} + listOf(
    pausedMvn("JenkinsPreCommit", "ASF Jenkins PreCommit (JDK 17)", "ASF Jenkins Jenkinsfile-PreCommit",
        "pull-request builds only; this project builds the fork's default branch, and PR building is not set up", 17,
        jenkinsArgs),
    pausedMvn("JenkinsOwasp", "ASF Jenkins OWASP dependency-check (JDK 17)", "ASF Jenkins Jenkinsfile-owasp",
        "security scan side workflow; dependency-check downloads the full NVD database (needs an NVD API key to be practical, none provisioned)",
        17, "clean package -DskipTests dependency-check:check"),
)

val TypoCheck = BuildType({
    id("Side_TypoCheck")
    name = "[paused] Typo Check"
    description = "GHA ci.yaml job typo-check (crate-ci/typos@v1.22.4) · PAUSED: upstream runs it on pull_request only; this project builds the default branch, never PRs"
    paused = true
    sources()
    params {
        common(17)
        param("env.MF_TYPOS_VERSION", "1.22.4")
    }
    steps { bashStep("typos", "typos.sh") }
    requirements { linux(Tier.SMALL) }
    failureConditions { executionTimeoutMin = 10 }
})

val ManualBuild = BuildType({
    id("Side_ManualBuild")
    name = "[paused] Manual Build (workflow_dispatch)"
    description = "GHA manual.yaml (workflow_dispatch, JDK 17, arbitrary ref incl. refs/pull/*) · PAUSED: manual-only upstream, and arbitrary/PR refs need a wider branch spec than this mirror's master-only root"
    paused = true
    sources()
    params {
        common(17)
        // workflow_dispatch inputs → TeamCity prompt params. buildRef maps to the custom-run branch.
        text("mf.mvnOpts", "--fail-at-end", label = "Maven options", display = ParameterDisplay.PROMPT, allowEmpty = true)
        text("mf.goals", "-Pfull-build apache-rat:check verify -DskipTests spotbugs:check checkstyle:check javadoc:jar",
            label = "Maven goals", display = ParameterDisplay.PROMPT, allowEmpty = false)
        param("env.MF_MVN_ARGS", "%mf.mvnOpts% %mf.goals%")
    }
    steps {
        bashStep("Install C dependencies", "c-deps.sh")
        bashStep("Build with Maven", "mvn-ci.sh")
    }
    requirements { linux(Tier.MEDIUM) }
    failureConditions { executionTimeoutMin = 360 }
})

val pausedTypes: List<BuildType> = jenkinsTypes + TypoCheck + ManualBuild

// ---------------------------------------------------------------- composite

val All = BuildType({
    id("All")
    name = "All (GitHub Actions parity)"
    type = BuildTypeSettings.Type.COMPOSITE
    description = "Composite of every live cell: ci.yaml mvn ×4, e2e.yaml compatibility ×8, scripts.yaml ×2, website.yaml ×1. " +
        "Upstream runs these as 4 independent workflows on every push; green here = all four workflows green."

    vcs {
        root(SourcesVcs)
        showDependenciesChanges = true
    }
    triggers {
        // Upstream runs on every push. Disabled until the repo is accepted, so syncing the mirror doesn't
        // fire 15 cells on the shared demo server.
        vcs { enabled = false; branchFilter = "+:<default>" }
    }
    // Snapshot only (same revision, one chain): the composite consumes no files (Lesson 6), and upstream's
    // jobs share no artifacts. Paused lanes are left out on purpose: a snapshot dependency on a paused config
    // would pull an unrunnable build into the chain and leave it waiting forever.
    dependencies {
        liveTypes.forEach { snapshot(it) { onDependencyFailure = FailureAction.ADD_PROBLEM } }
    }
})

// Relative-id hierarchy: this project's id (TcMf_ApacheZookeeper) and name ("apache/zookeeper (migration
// factory)") are set when the server project is created at the approval checkpoint; every id() above is
// prefixed with it.
project {
    description = "Generated by the TeamCity migration factory from apache/zookeeper GitHub Actions. See work/design/apache__zookeeper.md."

    vcsRoot(SourcesVcs)
    buildType(All)

    subProject {
        id("Ci")
        name = "CI (ci.yaml)"
        mvnTypes.forEach { buildType(it) }
    }
    subProject {
        id("E2e")
        name = "End to End Tests (e2e.yaml)"
        e2eTypes.forEach { buildType(it) }
    }
    subProject {
        id("ScriptQa")
        name = "ScriptQA (scripts.yaml)"
        scriptQaTypes.forEach { buildType(it) }
    }
    buildType(Website)
    subProject {
        id("Side")
        name = "Side workflows (paused)"
        pausedTypes.forEach { buildType(it) }
    }
}
